-- The append-only log (02-architecture/event-log.md).
--
-- Generated by `drizzle-kit generate` from drizzle/schema.ts, then extended
-- with the two triggers below, which are hand-written because they are the
-- invariant rather than a shape.

CREATE TABLE `log_entries` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`timestamp` text NOT NULL,
	`actor_type` text NOT NULL,
	`actor_id` text,
	`payload` text NOT NULL,
	`compensation_for` text,
	`schema_version` integer NOT NULL,
	`device_id` text NOT NULL,
	`seq` integer NOT NULL,
	`sync` integer DEFAULT true NOT NULL
);
