CREATE INDEX `log_entries_order_idx` ON `log_entries` (`timestamp`,`device_id`,`seq`);
--> statement-breakpoint
CREATE INDEX `log_entries_device_seq_idx` ON `log_entries` (`device_id`,`seq`);
--> statement-breakpoint
CREATE INDEX `log_entries_type_idx` ON `log_entries` (`type`);
--> statement-breakpoint
CREATE INDEX `log_entries_compensation_idx` ON `log_entries` (`compensation_for`);
--> statement-breakpoint
-- "The log is append-only. Log entries are never mutated and never deleted."
-- Making that a trigger rather than a convention is the same move
-- `02-architecture/projections.md` makes for protocol immutability: a bug or a
-- sync from another device cannot do the forbidden thing either.
--
-- A deliberate local-data reset would have to drop these first. That is a
-- decision the docs have not made, which is exactly why it should be loud.
CREATE TRIGGER `log_entries_no_update`
BEFORE UPDATE ON `log_entries`
BEGIN
	SELECT RAISE(ABORT, 'the log is append-only: entries are never mutated');
END;
--> statement-breakpoint
CREATE TRIGGER `log_entries_no_delete`
BEFORE DELETE ON `log_entries`
BEGIN
	SELECT RAISE(ABORT, 'the log is append-only: entries are never deleted');
END;
